<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import {AlertCircle,Check,LoaderCircle,RefreshCw,ShieldCheck,X} from 'lucide-vue-next';
import ApprovalReview from './ApprovalReview.vue';
import BiLoadStatus from './BiLoadStatus.vue';
import {createRequestGuard} from '../lib/async-response';
import {conversationReviewState} from '../lib/conversation-approvals';
type Item=Record<string,any>;
const props=defineProps<{tenant:string;tenantName:string;resource:Item;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const guard=createRequestGuard();const busy=ref(false);const error=ref('');const review=ref<Item|null>(null);const executions=ref<Item[]>([]);const uncertain=ref(false);const clock=ref(Date.now());const requestId=crypto.randomUUID();let timer:ReturnType<typeof setInterval>|undefined;let polling=false;
const state=computed(()=>review.value?conversationReviewState(review.value,clock.value):'');const pending=computed(()=>['approved','executing'].includes(state.value));
async function history(){if(polling)return;const valid=guard.next();polling=true;try{const data=await props.request(`/catalog/${props.tenant}/schedules/${props.resource.id}/loads`);if(!valid())return;executions.value=data.executions;if(review.value&&pending.value)review.value=(await props.request(`/bi-actions/${review.value.id}`)).approval;}catch(e){if(valid())error.value=(e as Error).message;}finally{if(valid())polling=false;}}
async function begin(){if(busy.value)return;busy.value=true;error.value='';try{const result=await props.request(`/catalog/${props.tenant}/schedules/${props.resource.id}/loads`,'POST',{request_id:requestId});review.value=result.approval;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function decide(decision:string){if(!review.value||busy.value)return;busy.value=true;error.value='';try{review.value=await props.request(`/approvals/${review.value.id}/decide`,'POST',{decision,fingerprint:review.value.fingerprint});uncertain.value=false;void history();}catch(e){uncertain.value=true;error.value=(e as Error).message;}finally{busy.value=false;}}
async function confirm(){if(!review.value)return;busy.value=true;try{review.value=(await props.request(`/bi-actions/${review.value.id}`)).approval;uncertain.value=false;error.value='';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(()=>{void history();timer=setInterval(()=>{clock.value=Date.now();if(!document.hidden)void history();},5000);});onUnmounted(()=>{guard.invalidate();if(timer)clearInterval(timer);});
</script>
<template><section class="schedule-run" data-tour="schedule-run"><header><div><h3>Atualizar os dados agora</h3><p>Solicite uma carga e confira o resultado de cada fonte. Os horários da agenda serão preservados.</p></div><button v-if="!review" class="primary-button" :disabled="busy||resource.active===false" @click="begin"><LoaderCircle v-if="busy" class="spin" :size="15"/><RefreshCw v-else :size="15"/>{{busy?'Conferindo fontes…':'Atualizar agora'}}</button></header><p v-if="resource.active===false" class="resource-note">Esta agenda está inativa. Confira a configuração e autorize sua ativação antes de executar.</p>
 <template v-if="review"><template v-if="state==='pending'"><ApprovalReview :approval="review" :tenants="[{id:tenant,name:tenantName}]"/><div class="schedule-run-actions"><button class="secondary-button" :disabled="busy||uncertain" @click="decide('rejected')"><X :size="15"/>Recusar</button><button class="primary-button" :disabled="busy||uncertain" @click="decide('approved')"><ShieldCheck :size="15"/>Autorizar atualização</button></div></template><p v-else-if="pending" role="status"><LoaderCircle class="spin" :size="15"/> Registrando o pedido no BI…</p><p v-else-if="state==='failed'" class="form-error">{{review.payload?.execution?.message??'Confira o pedido e o histórico antes de repetir.'}}</p><p v-else-if="state==='unavailable'" class="resource-note">Não foi possível conferir a revisão. Use Conferir solicitação para recuperar o estado antes de decidir.</p><p v-else-if="state!=='completed'" class="resource-note">Esta revisão foi encerrada sem um novo envio.</p><button v-if="uncertain||state==='unavailable'" class="secondary-button" :disabled="busy" @click="confirm">Conferir solicitação</button></template>
 <p v-if="error" class="form-error" role="alert"><AlertCircle :size="15"/>{{error}}</p><BiLoadStatus v-for="execution in executions" :key="execution.id" :execution="execution" :request="request"/><p v-if="!executions.length&&!pending" class="resource-note">Os pedidos feitos por você neste portal ficarão disponíveis aqui, mesmo após fechar a página. O histórico do BI também inclui cargas automáticas.</p></section></template>
<style scoped>.schedule-run{margin:20px 0;padding:20px;border:1px solid #e1e8f3;border-radius:10px;background:#fff}.schedule-run>header{display:flex;gap:15px;align-items:center;justify-content:space-between}.schedule-run h3{font-size:14px;color:#36577f;margin:0}.schedule-run p{font-size:12px;color:#7f91ac;line-height:1.8}.schedule-run header p{margin:7px 0}.schedule-run .primary-button,.schedule-run .secondary-button{font-size:11px;white-space:nowrap}.schedule-run-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:9px}.schedule-run>p[role='status']{display:flex;align-items:center;gap:8px}@media(max-width:600px){.schedule-run{padding:15px}.schedule-run>header{align-items:flex-start;flex-direction:column}}</style>
